package com.camarodiag.gen5.ui

import com.camarodiag.connectors.J1979FreezeUsbCapture
import com.camarodiag.gen5.data.obd.J1979FreezePrefix
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.ensureActive

/** Independent verification of a CF/1 prefix report generated by any host.
 *
 * The original CF/1 bytes and independently known VIN are mandatory. There
 * is no trust in report counters, status flags, document property order or
 * a claimed transport. An interrupted capture cannot prove a completed
 * campaign, ECU authenticity, or permission for programming.
 */
internal object J1979FreezePrefixVerification {
    const val MAX_REPORT_BYTES = 32 * 1024 * 1024
    const val SCHEMA = "camarodiag-j1979-native-freeze-prefix-verification-v1"

    data class Verified(
        val document: Map<String,Any?>,
        val bytes: ByteArray,
        val captureSha: String,
        val reportSha: String
    )

    suspend fun verify(capture: ByteArray, report: ByteArray, vin: String): Verified {
        require(capture.isNotEmpty() && capture.size.toLong() <= J1979FreezeUsbCapture.MAX_CAPTURE) {
            "CF/1 source exceeds byte limit"
        }
        require(report.isNotEmpty() && report.size <= MAX_REPORT_BYTES) {
            "CF/1 prefix report exceeds byte limit"
        }
        require(J1979CatalogueProjection.validVin(vin)) { "Independent VIN required" }
        currentCoroutineContext().ensureActive()
        val originalSha = J1979DocumentedCatalogue.sha(capture)
        val generated = J1979FreezePrefix.inspect(capture,vin).toMutableMap()
        generated["capture_sha256"] = originalSha
        // Parse *both* sides with the same bounded, strict JSON decoder.
        // Integer normalization is required because a native Kotlin Int and
        // an imported JSON integer have different runtime representations.
        val authoritativeBytes = J1979CatalogueJson.encode(generated)
        val expected = J1979CatalogueJson.parse(authoritativeBytes,MAX_REPORT_BYTES)
        val supplied = J1979CatalogueJson.parse(report,MAX_REPORT_BYTES)
        require(supplied == expected) {
            "CF/1 prefix report differs from independent replay"
        }
        currentCoroutineContext().ensureActive()
        val reportSha = J1979DocumentedCatalogue.sha(report)
        val verification = linkedMapOf<String,Any?>(
            "schema" to SCHEMA,
            "consistent" to true,
            "prefix_integrity_verified" to true,
            "capture_integrity_verified" to false,
            "execution_completed" to false,
            "physical_vehicle_verified" to false,
            "permits_programming" to false,
            "capture_sha256" to originalSha,
            "report_sha256" to reportSha,
            "complete_records" to generated["complete_records"],
            "complete_observations" to generated["complete_observations"],
            "interruption" to generated["interruption"]
        )
        return Verified(verification,J1979CatalogueJson.encode(verification),originalSha,reportSha)
    }
}
